sp_page.css:
/* Make the main page container use full width */
.container {
    width: 100% !important;
    max-width: 100% !important;
    padding-left: 15px !important;
    padding-right: 15px !important;
}

/* Remove unwanted spacing around the widget */
.row {
    margin-left: 0 !important;
    margin-right: 0 !important;
}

/* File Manager widget positioning */
.panel,
.widget,
.sp-widget {
    width: 100% !important;
    max-width: 100% !important;
}

/* Avoid horizontal overflow */
body {
    overflow-x: hidden;
}
